import{_ as n,C as r,o as e,c as l,a5 as g,E as d,j as o,a as i}from"./chunks/framework.DuVjalqf.js";const h="/rb_cobot_docs_muscat/images/program/set-form.avif",c="/rb_cobot_docs_muscat/images/program/set-options.avif",P=JSON.parse('{"title":"설정","description":"","frontmatter":{"title":"설정","outline":[2,3]},"headers":[],"relativePath":"manual/program/set.md","filePath":"manual/program/set.md","lastUpdated":1792487136000}'),b={name:"manual/program/set.md"};function p(m,t,u,_,x,f){const a=r("DemoFrame"),s=r("ScenarioSteps");return e(),l("div",null,[t[0]||(t[0]=g('<h1 id="설정" tabindex="-1">설정 <a class="header-anchor" href="#설정" aria-label="Permalink to &quot;설정&quot;">​</a></h1><p><strong>설정</strong>은 프로그램 실행 도중 로봇의 <strong>동작 설정을 바꾸는</strong> 명령입니다. 충돌 감지, 속도, 좌표계, 직접 교시, 입출력 마스크 등 여러 종류의 설정을 하나의 명령으로 바꿀 수 있습니다. 설정 명령 하나는 <strong>한 종류의 설정</strong>만 담으므로, 여러 설정을 바꾸려면 설정 명령을 여러 개 넣습니다.</p><p>이 문서에서는 <strong>프로그램</strong> 화면에서 다음을 해 봅니다.</p><ul><li>설정 명령을 추가하고 외부 충돌 감지를 켜는 설정 만들기</li><li>같은 명령의 종류를 속도 조절 바로 바꾸기</li><li>고를 수 있는 설정 종류 확인하기</li></ul><div class="warning custom-block"><p class="custom-block-title">안전</p><p>설정은 프로그램을 <strong>실행하면 로봇의 동작 설정이 실제로 바뀌는</strong> 명령입니다. 충돌 감지를 끄거나 속도를 높이면 안전에 영향을 줄 수 있으니 값을 확인하고 사용합니다.</p></div><h2 id="설정-화면" tabindex="-1">설정 화면 <a class="header-anchor" href="#설정-화면" aria-label="Permalink to &quot;설정 화면&quot;">​</a></h2><p>트리의 설정을 누르면 열리는 화면입니다. 설정 명령을 처음 추가하면 <strong>외부 충돌 감지</strong>가 골라져 있고 상태는 <strong>끄기</strong>입니다.</p><p><img src="'+h+'" alt="설정 화면"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td style="text-align:center;">①</td><td><strong>옵션</strong></td><td>바꾸려는 설정의 종류입니다. 아래 영역이 고른 종류의 설정 항목으로 바뀝니다. 종류는 아래 표에서 모두 설명합니다.</td></tr><tr><td style="text-align:center;">②</td><td><strong>상태</strong></td><td>외부 충돌 감지를 끄기·켜기 중에서 고릅니다.</td></tr><tr><td style="text-align:center;">③</td><td><strong>정지 모드</strong></td><td>동작 일시 정지·회피 정지 중에서 고릅니다.</td></tr><tr><td style="text-align:center;">④</td><td><strong>둔감도</strong></td><td>0~100% 슬라이더입니다. 값이 클수록 더 큰 힘이 가해져야 충돌로 판단합니다.</td></tr><tr><td style="text-align:center;">⑤</td><td><strong>닫기</strong></td><td>설정 화면을 닫습니다. 저장하지 않은 변경이 있으면 저장하지 않고 닫을지 묻습니다.</td></tr><tr><td style="text-align:center;">⑥</td><td><strong>저장</strong></td><td>설정을 적용하고 설정 화면을 닫습니다. 트리의 설정 옆에 설정 내용이 표시됩니다.</td></tr></tbody></table></div><p>②~④는 <strong>외부 충돌 감지</strong>를 골랐을 때의 항목이며, 설정 &gt; 일반 &gt; 충돌 감지의 <a href="/rb_cobot_docs_muscat/manual/settings/collision-detection">외부 충돌</a> 설정과 같은 항목입니다. 다른 종류를 고르면 ②~④ 자리에 그 종류의 항목이 나타납니다. 트리에는 <code>Out Collision - On, Evasion Stop, Threshold: 50%</code>처럼 고른 값이 요약되어 표시됩니다.</p><h2 id="설정-종류" tabindex="-1">설정 종류 <a class="header-anchor" href="#설정-종류" aria-label="Permalink to &quot;설정 종류&quot;">​</a></h2><p>옵션 선택 상자를 누르면 설정 종류 목록이 열립니다. 목록이 길어 스크롤해서 볼 수 있습니다.</p><p><img src="'+c+'" alt="옵션 목록"></p><p>설정 종류는 모두 30가지입니다. 종류별로 정하는 항목은 다음과 같습니다.</p><h3 id="충돌·안전" tabindex="-1">충돌·안전 <a class="header-anchor" href="#충돌·안전" aria-label="Permalink to &quot;충돌·안전&quot;">​</a></h3><table tabindex="0"><thead><tr><th>종류</th><th>정하는 항목</th></tr></thead><tbody><tr><td><strong>외부 충돌 감지</strong></td><td>상태(끄기·켜기), 정지 모드(동작 일시 정지·회피 정지), 둔감도</td></tr><tr><td><strong>자가 충돌 감지</strong></td><td>모드(자가 충돌 직전 멈춤·자가 충돌시 속도 제어), 내부 거리(mm), 외부 거리(mm)</td></tr><tr><td><strong>자가 충돌 감지 해제</strong></td><td>감지 해제 시간(초)</td></tr><tr><td><strong>동작 정지/차단</strong></td><td>정지/차단 모드(해제·지속 차단·일회성 정지), 정지 시간(초)</td></tr><tr><td><strong>작동 범위 확인</strong></td><td>확인 모드(확인 시작·확인 완료), 데이터 옵션(레퍼런스 값)</td></tr><tr><td><strong>손목 특이점 모드</strong></td><td>모드(기본값·특이점 회피)</td></tr></tbody></table><h3 id="속도·시간" tabindex="-1">속도·시간 <a class="header-anchor" href="#속도·시간" aria-label="Permalink to &quot;속도·시간&quot;">​</a></h3><table tabindex="0"><thead><tr><th>종류</th><th>정하는 항목</th></tr></thead><tbody><tr><td><strong>고정 속도</strong></td><td>동작 유형(J-Types·L-Types (Position)·L-Types (Orientation)), 속도 옵션(끄기·고정 모드: %·고정 모드: 물리)과 속도, 가속도 옵션(같은 선택지)과 가속도. 옵션이 끄기이면 그 값은 입력할 수 없습니다.</td></tr><tr><td><strong>속도 조절 바</strong></td><td>속도 조절 바(%) 슬라이더</td></tr><tr><td><strong>시간 제약</strong></td><td>모드(끄기·단위 동작 시간 구속·다중 동작 시간 구속), 시간</td></tr><tr><td><strong>TCP 속도 제한</strong></td><td>제한 모드(끄기(시스템 기본)·켜기), TCP 속도</td></tr><tr><td><strong>Jacobian 기반 속도 제어</strong></td><td>모드(활성·비활성)</td></tr><tr><td><strong>관절 지령 필터</strong></td><td>필터 모드(끄기(시스템 기본)·사용자 지정 필터 조정), 필터</td></tr></tbody></table><h3 id="직접-교시·제어" tabindex="-1">직접 교시·제어 <a class="header-anchor" href="#직접-교시·제어" aria-label="Permalink to &quot;직접 교시·제어&quot;">​</a></h3><table tabindex="0"><thead><tr><th>종류</th><th>정하는 항목</th></tr></thead><tbody><tr><td><strong>직접 교시 모드</strong></td><td>모드(끄기·직접 교시 활성화·버튼 클릭 시 활성화), 직접 교시 감도, 추가 힘 프레임(전역 좌표계·로컬 TCP 좌표계·사용자 좌표계), 추가 힘</td></tr><tr><td><strong>조인트 임피던스 제어</strong></td><td>모드(끄기·조인트 임피던스 활성화), 강성, 토크 제한</td></tr><tr><td><strong>마스터 모드 선택</strong></td><td>모드(끄기·반영된 조인트 각도·동기화된 직교 좌표)</td></tr><tr><td><strong>진동 (토크 기반)</strong></td><td>모드(끄기·켜기), 시간, 주기, 강도</td></tr><tr><td><strong>진동 (모션 기반)</strong></td><td>모드(끄기·켜기), 좌표계 선택(전역·로컬·사용자·목표·활성화된 로컬 좌표계), 진폭, 주기, 위상</td></tr><tr><td><strong>부가 축 동기화</strong></td><td>동기화 모드(동기화 끄기·켜기)</td></tr><tr><td><strong>프로그램 흐름 변경</strong></td><td>목표 컴포넌트(모든 로봇 컴포넌트·현재 컴포넌트), 옵션(중지·일시 정지·재개·충돌 초기화)</td></tr><tr><td><strong>FT 센서 소프트웨어 영점 조정</strong></td><td>모드(Start Software Nulling·Return to Original value)</td></tr></tbody></table><h3 id="좌표계·시프트" tabindex="-1">좌표계·시프트 <a class="header-anchor" href="#좌표계·시프트" aria-label="Permalink to &quot;좌표계·시프트&quot;">​</a></h3><table tabindex="0"><thead><tr><th>종류</th><th>정하는 항목</th></tr></thead><tbody><tr><td><strong>사용자 좌표계 선택</strong></td><td>사용할 사용자 좌표계(이름 목록에서 선택)</td></tr><tr><td><strong>사용자 좌표계: XYZ를 통한 설정</strong></td><td>사용자 좌표계, 설정 옵션(저장된 값 복원·목표값 적용(임시)·목표 영구 저장), 목표 좌표계(전역·로컬·사용자)와 값</td></tr><tr><td><strong>사용자 좌표계: TCP를 통한 설정</strong></td><td>사용자 좌표계, 설정 옵션</td></tr><tr><td><strong>사용자 좌표계: 3개 지점을 통한 설정</strong></td><td>사용자 좌표계, 설정 옵션, 포인트 순서(원점→X축→XY 평면·원점→Y축→YZ 평면·원점→Z축→ZX 평면), 포인트</td></tr><tr><td><strong>목표 시프트: 수동 설정</strong></td><td>시프트 번호, 시프트, 시프트 모드(끄기·L-이동 조정·L, J-이동 조정·J-이동 조정), 기준 좌표계, 이동 단위</td></tr><tr><td><strong>목표 시프트: 랜드마크를 통한 설정</strong></td><td>시프트 모드, 허용 오차, 기준점, 현재점</td></tr></tbody></table><h3 id="입출력·통신·기타" tabindex="-1">입출력·통신·기타 <a class="header-anchor" href="#입출력·통신·기타" aria-label="Permalink to &quot;입출력·통신·기타&quot;">​</a></h3><table tabindex="0"><thead><tr><th>종류</th><th>정하는 항목</th></tr></thead><tbody><tr><td><strong>디지털 입력 함수 마스크</strong></td><td>목표 장치(제어 박스 I/O·확장 I/O·툴 플랜지 I/O), 포트 선택(전체 포트 또는 포트별), 옵션(비활성화 마스크 끄기·켜기)</td></tr><tr><td><strong>디지털 출력 함수 마스크</strong></td><td>목표 장치, 포트 선택, 옵션</td></tr><tr><td><strong>ASCII 함수 호출</strong></td><td>옵션(직접 실행·메시지 Que), 메시지</td></tr><tr><td><strong>관절 원점 캘리브레이션</strong></td><td>옵션(데이터 테이블 초기화·추가·테이블 결과 계산·로봇팔에 결과 반영), 관절 각도, TCP 실측값, 계산 옵션(위치 정보 사용·위치 및 회전 정보 사용), 비밀번호</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">종류를 바꾸면</p><p>옵션에서 다른 종류를 고르면 아래 영역이 그 종류의 항목으로 바뀝니다. 저장하면 <strong>마지막으로 고른 종류의 설정</strong>만 이 명령에 남습니다.</p></div><h2 id="직접-해-보기" tabindex="-1">직접 해 보기 <a class="header-anchor" href="#직접-해-보기" aria-label="Permalink to &quot;직접 해 보기&quot;">​</a></h2><p>설정 명령을 추가해 외부 충돌 감지를 켜고 회피 정지로 정한 뒤, 같은 명령을 속도 조절 바 설정으로 바꿔 봅니다. 실습의 로봇은 실제로 움직이지 않으며 프로그램을 실행하지 않습니다. 다음 순서로 진행합니다.</p><ol><li>트리의 빈 영역을 눌러 위치를 정하고 편집 아이콘으로 명령어 목록을 연 뒤 <strong>설정</strong>을 추가합니다. 처음에는 외부 충돌 감지가 골라져 있고 상태는 끄기입니다.</li><li>트리에서 설정을 눌러 설정 화면을 엽니다.</li><li>상태를 <strong>켜기</strong>, 정지 모드를 <strong>회피 정지</strong>로 고르고 둔감도 슬라이더를 움직여 봅니다.</li><li><strong>저장</strong>을 누르면 트리의 설정 옆에 <code>Out Collision - On</code>과 정지 모드, 둔감도가 표시됩니다.</li><li>설정을 다시 열어 옵션을 <strong>속도 조절 바</strong>로 바꾸고 슬라이더로 값을 정합니다.</li><li><strong>저장</strong>을 누르면 트리의 설정 옆 내용이 속도 조절 바 설정으로 바뀝니다.</li></ol>',28)),d(a,{id:"program-set"}),t[1]||(t[1]=o("h2",{id:"사용-방법",tabindex:"-1"},[i("사용 방법 "),o("a",{class:"header-anchor",href:"#사용-방법","aria-label":'Permalink to "사용 방법"'},"​")],-1)),d(s,{id:"program-set"})])}const q=n(b,[["render",p]]);export{P as __pageData,q as default};
